import math
from collections import Counter


def bm25_rank(query, docs, k1=1.5, b=0.75):
    if not docs:
        return []
    tokens = [d.lower().split() for d in docs]
    n_docs = len(tokens)
    avgdl = sum(len(t) for t in tokens) / n_docs
    if avgdl == 0:
        return []
    tfs = [Counter(t) for t in tokens]
    df = Counter(term for tf in tfs for term in tf)   # each doc counted once per term

    def idf(term):
        n = df.get(term, 0)
        return math.log((n_docs - n + 0.5) / (n + 0.5) + 1)

    q_terms = query.lower().split()
    results = []
    for i, tf in enumerate(tfs):
        dl = len(tokens[i])
        score = 0.0
        for t in q_terms:
            f = tf.get(t, 0)
            if f:
                score += idf(t) * f * (k1 + 1) / (f + k1 * (1 - b + b * dl / avgdl))
        if score > 0:
            results.append([i, round(score, 4)])
    results.sort(key=lambda r: (-r[1], r[0]))
    return results
